/**
 * warehouse-breakdown-tooltip.tsx
 * Solid-based tooltips for displaying a Civilization's Syncretism Unlocks
 */
import { Component, createMemo, For, ParentComponent, Show, splitProps } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import {
	Tooltip,
	TooltipBaseProps,
	TooltipHorizontalPosition,
	TooltipVerticalPosition,
} from "#core/ui-next/components/tooltip.jsx";
import { AgeIcon } from "#core/ui-next/screens/create-game/age-icon.jsx";
import { SyncretismDataModel, SyncretismUnlockOption } from "#core/ui-next/screens/create-game/syncretism-model.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

interface SyncretismTooltipProps extends Omit<TooltipBaseProps, "initialVPosition" | "initialHPosition" | "offset"> {
	initialVPosition?: TooltipVerticalPosition;
	initialHPosition?: TooltipHorizontalPosition;
	offset?: number;
	civilizationType: string;
}

import style from "./civ-select-screen.scss?url";

const SyncretismEntry: Component<SyncretismUnlockOption> = (props) => {
	const icon = createMemo(() => {
		if (props.Kind == "KIND_QUARTER") return "CITY_UNIQUE_QUARTER";
		return props.Type;
	});

	return (
		<div class="flex flex-row items-center">
			<Icon
				class="size-8 mr-2"
				name={icon()}
			/>
			<div class="self-stretch w-0\.5 bg-primary-3 mr-2" />
			<div class="flex flex-col pr-13">
				<L10n.Stylize
					class="uppercase text-tertiary-1 text-sm font-title uppercase"
					text={props.Name}
				/>
				<L10n.Stylize
					class="text-sm create-game-markup tight"
					text={props.Description}
				/>
			</div>
		</div>
	);
};

export const SyncretismTooltipComponent: ParentComponent<SyncretismTooltipProps> = (props) => {
	const [local, other] = splitProps(props, ["children", "class", "civilizationType"]);
	const civData = createMemo(() => SyncretismDataModel.Info.get(local.civilizationType)!);

	return (
		<Tooltip {...other}>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content class={local.class}>
				<Tooltip.Frame class={"w-128"}>
					<div class="flex flex-col items-stretch">
						<div class="flex flex-col mb-1 items-center">
							<L10n.Stylize
								class="uppercase text-tertiary-1 font-title uppercase"
								text={civData().CivilizationName}
							/>
							<div class="flex flex-row items-center">
								<AgeIcon
									ageId={civData().AgeType}
									class="mr-2 size-8"
								/>
								<span class="uppercase text-sm text-accent-2">
									<L10n.Compose
										text="LOC_UI_CREATE_GAME_AVAILABLE_IN_THE_AGE"
										args={[civData().AgeName]}
									/>
								</span>
							</div>
						</div>
						<div class="flex flex-col gap-2">
							<Show when={civData().Infrastructure.length > 0}>
								<div class="civ-details-card-outer">
									<L10n.Stylize
										class="uppercase text-accent-2 my-1 ml-4"
										text="LOC_CREATE_GAME_UNLOCK_SYNCRETISM_INFRASTRUCTURE"
									/>
									<div class="civ-details-card-inner flex flex-col gap-1">
										<For each={civData().Infrastructure}>
											{(unlock, index) => (
												<>
													<Show when={index() != 0}>
														<div class="self-stretch h-0\.5 bg-primary-3 mr-2" />
													</Show>
													<SyncretismEntry {...unlock} />
												</>
											)}
										</For>
									</div>
								</div>
							</Show>
							<Show when={civData().Unit.length > 0}>
								<div class="civ-details-card-outer">
									<L10n.Stylize
										class="uppercase text-accent-2 my-1 ml-4"
										text="LOC_CREATE_GAME_UNLOCK_SYNCRETISM_UNITS"
									/>
									<div class="civ-details-card-inner flex flex-col gap-1">
										<For each={civData().Unit}>
											{(unlock, index) => (
												<>
													<Show when={index() != 0}>
														<div class="self-stretch h-0\.5 bg-primary-3 mr-2" />
													</Show>
													<SyncretismEntry {...unlock} />
												</>
											)}
										</For>
									</div>
								</div>
							</Show>
						</div>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const SyncretismTooltip = ComponentRegistry.register({
	name: "SyncretismTooltip",
	createInstance: SyncretismTooltipComponent,
	images: ["blp:base_ticket-bg", "blp:shell_line-divider"],
	styles: [style],
});
